'use strict';

// MODULES //

var tape = require( 'tape' );
var Float32Array = require( '@stdlib/array/float32' );
var sindexOfLessThanSorted = require( './../lib/sindex_of_less_than_sorted.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof sindexOfLessThanSorted, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 4', function test( t ) {
	t.strictEqual( sindexOfLessThanSorted.length, 4, 'has expected arity' );
	t.end();
});

tape( 'the function returns the index of the first element in a sorted strided array which is less than a provided search element', function test( t ) {
	var actual;
	var x;

	x = new Float32Array( [ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ] );

	actual = sindexOfLessThanSorted( x.length, 2.0, x, 1 );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});

tape( 'the function returns the index of the first element in a sorted strided array which is less than a provided search element when the search element is not present in the strided array', function test( t ) {
	var actual;
	var x;

	x = new Float32Array( [ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ] );

	actual = sindexOfLessThanSorted( x.length, 1.5, x, 1 );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-1` if every indexed element in the array is greater than or equal to the search element', function test( t ) {
	var actual;
	var x;

	x = new Float32Array( [ 2.0, 2.0, 2.0 ] );

	actual = sindexOfLessThanSorted( x.length, 2.0, x, 1 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-1` if a provided `N` parameter is less than or equal to zero', function test( t ) {
	var actual;
	var x;

	x = new Float32Array( [ 1.0, 2.0, 3.0 ] );

	actual = sindexOfLessThanSorted( 0, 2.0, x, 1 );
	t.strictEqual( actual, -1, 'returns expected value' );

	actual = sindexOfLessThanSorted( -1, 2.0, x, 1 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-1` if comparisons involve `NaN` values', function test( t ) {
	var actual;
	var x;

	x = new Float32Array( [ 0.0, 1.0 ] );

	actual = sindexOfLessThanSorted( 2, NaN, x, 1 );
	t.strictEqual( actual, -1, 'returns expected value' );

	x = new Float32Array( [ NaN, NaN ] );

	actual = sindexOfLessThanSorted( 2, 0.0, x, 1 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});

tape( 'the function treats `-0` and `+0` as equal', function test( t ) {
	var actual;
	var x;

	x = new Float32Array( [ 0.0 ] );

	actual = sindexOfLessThanSorted( 1, -0.0, x, 1 );
	t.strictEqual( actual, -1, 'returns expected value' );

	x = new Float32Array( [ -0.0 ] );

	actual = sindexOfLessThanSorted( 1, 0.0, x, 1 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});

tape( 'the function supports an `x` stride', function test( t ) {
	var actual;
	var x;

	x = new Float32Array([
		1.0, // 0
		9.0,
		2.0, // 1
		9.0,
		3.0  // 2
	]);

	actual = sindexOfLessThanSorted( 3, 2.0, x, 2 );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});

tape( 'the function supports a negative `x` stride', function test( t ) {
	var actual;
	var x;

	x = new Float32Array([
		3.0, // 2
		9.0,
		2.0, // 1
		9.0,
		1.0  // 0
	]);

	actual = sindexOfLessThanSorted( 3, 2.0, x, -2 );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});

tape( 'the function supports complex access patterns', function test( t ) {
	var actual;
	var x;

	x = new Float32Array([
		1.0, // 0
		9.0,
		2.0, // 1
		9.0,
		3.0  // 2
	]);

	actual = sindexOfLessThanSorted( 3, 2.0, x, 2 );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});

tape( 'the function supports view offsets', function test( t ) {
	var actual;
	var x0;
	var x1;

	x0 = new Float32Array( [ 9.0, 1.0, 2.0, 3.0, 4.0 ] );
	x1 = new Float32Array( x0.buffer, x0.BYTES_PER_ELEMENT*1 );

	actual = sindexOfLessThanSorted( 3, 2.0, x1, 1 );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});

tape( 'the function returns the index of the first element in a sorted strided array which is less than a provided search element (descending order)', function test( t ) {
	var actual;
	var x;

	x = new Float32Array( [ 3.0, 3.0, 2.0, 2.0, 1.0, 1.0 ] );

	actual = sindexOfLessThanSorted( x.length, 2.0, x, 1 );
	t.strictEqual( actual, 4, 'returns expected value' );

	t.end();
});

tape( 'the function returns the index of the first element in a sorted strided array which is less than a provided search element when the search element is not present in the strided array (descending order)', function test( t ) {
	var actual;
	var x;

	x = new Float32Array( [ 3.0, 3.0, 2.0, 2.0, 1.0, 1.0 ] );

	actual = sindexOfLessThanSorted( x.length, 1.5, x, 1 );
	t.strictEqual( actual, 4, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-1` if every indexed element in the array is greater than or equal to the search element (descending order)', function test( t ) {
	var actual;
	var x;

	x = new Float32Array( [ 3.0, 2.0, 1.0 ] );

	actual = sindexOfLessThanSorted( x.length, 1.0, x, 1 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});

tape( 'the function supports an `x` stride (descending order)', function test( t ) {
	var actual;
	var x;

	x = new Float32Array([
		3.0, // 0
		9.0,
		2.0, // 1
		9.0,
		1.0  // 2
	]);

	actual = sindexOfLessThanSorted( 3, 2.0, x, 2 );
	t.strictEqual( actual, 2, 'returns expected value' );

	t.end();
});

tape( 'the function supports a negative `x` stride (descending order)', function test( t ) {
	var actual;
	var x;

	x = new Float32Array([
		1.0, // 2
		9.0,
		2.0, // 1
		9.0,
		3.0  // 0
	]);

	actual = sindexOfLessThanSorted( 3, 2.0, x, -2 );
	t.strictEqual( actual, 2, 'returns expected value' );

	t.end();
});

tape( 'the function supports view offsets (descending order)', function test( t ) {
	var actual;
	var x0;
	var x1;

	x0 = new Float32Array( [ 9.0, 4.0, 3.0, 2.0, 1.0 ] );
	x1 = new Float32Array( x0.buffer, x0.BYTES_PER_ELEMENT*1 );

	actual = sindexOfLessThanSorted( 3, 3.0, x1, 1 );
	t.strictEqual( actual, 2, 'returns expected value' );

	t.end();
});

tape( 'the function supports input arrays containing `NaN` values', function test( t ) {
	var actual;
	var x;

	x = new Float32Array( [ 4.0, 3.0, NaN, 1.0 ] );

	actual = sindexOfLessThanSorted( x.length, 2.5, x, 1 );
	t.strictEqual( actual, 3, 'returns expected value' );

	x = new Float32Array( [ NaN, 3.0, 2.0, 1.0 ] );

	actual = sindexOfLessThanSorted( x.length, 2.5, x, 1 );
	t.strictEqual( actual, 2, 'returns expected value' );

	x = new Float32Array( [ 3.0, 2.0, 1.0, NaN ] );

	actual = sindexOfLessThanSorted( x.length, 2.5, x, 1 );
	t.strictEqual( actual, 1, 'returns expected value' );

	x = new Float32Array( [ 1.0, NaN, 3.0, 4.0 ] );

	actual = sindexOfLessThanSorted( x.length, 2.0, x, 1 );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});
